  --color-neutral-200:  #D9DBE9;
  --color-neutral-300:  #BFC4D4;
  --color-neutral-500:  #8B94A8;
  --color-neutral-700:  #6B7280;
  --color-neutral-800:  #404754;
  --color-neutral-900:  #1F2937;
  --color-neutral-1000: #031B4E;

  /* Semantic */
  --color-success-bg: #DDF4E4;
