  --bg-elevated: #FFFFFF;
  --bg-hero:     linear-gradient(180deg, #E5F1FF 0%, #FFFFFF 100%);
  --bg-overlay:  rgba(3,27,78,0.50);

  /* Text */
  --text-primary:    #031B4E;
